import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Goals & Objectives — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"goals-04-troubleshooting-and-faqs.md","filePath":"goals-04-troubleshooting-and-faqs.md"}'),i={name:"goals-04-troubleshooting-and-faqs.md"};function s(r,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="goals-objectives-—-troubleshooting-faqs" tabindex="-1">Goals &amp; Objectives — Troubleshooting &amp; FAQs <a class="header-anchor" href="#goals-objectives-—-troubleshooting-faqs" aria-label="Permalink to &quot;Goals &amp; Objectives — Troubleshooting &amp; FAQs&quot;">​</a></h1><hr><h2 id="the-expand-chevron-is-not-showing-on-a-goal" tabindex="-1">The expand chevron is not showing on a Goal <a class="header-anchor" href="#the-expand-chevron-is-not-showing-on-a-goal" aria-label="Permalink to &quot;The expand chevron is not showing on a Goal&quot;">​</a></h2><p>The chevron only appears when a Goal has at least one downstream connection — an object with this Goal as a parent, or a roadmap, release, or strategy that contains such an object.</p><p>If a Goal is new and has no linked objects yet, the chevron will not appear. Once you link an object to the Goal from that object&#39;s detail page (via the Parents field), the chevron will appear the next time the Goals list loads.</p><hr><h2 id="i-created-a-goal-but-it-doesn-t-show-a-typed-id" tabindex="-1">I created a Goal but it doesn&#39;t show a typed ID <a class="header-anchor" href="#i-created-a-goal-but-it-doesn-t-show-a-typed-id" aria-label="Permalink to &quot;I created a Goal but it doesn&#39;t show a typed ID&quot;">​</a></h2><p>Typed IDs require your organization to have a top-tier type configured with a prefix in Settings &gt; Taxonomy. If no top-tier type has been set, Goals are created without IDs.</p><p>To fix this: go to Settings &gt; Taxonomy, create or designate a top-tier type, and give it a prefix (e.g. GOAL, OBJ). Existing Goals will receive typed IDs automatically once the prefix is configured.</p><hr><h2 id="i-deleted-a-goal-—-what-happened-to-the-objects-that-were-linked-to-it" tabindex="-1">I deleted a Goal — what happened to the objects that were linked to it? <a class="header-anchor" href="#i-deleted-a-goal-—-what-happened-to-the-objects-that-were-linked-to-it" aria-label="Permalink to &quot;I deleted a Goal — what happened to the objects that were linked to it?&quot;">​</a></h2><p>Deleted Goal objects are orphaned, not deleted. They remain in the Backlog as top-level items with all their data intact (name, description, status, documents, quotes). The only thing that changes is the parent connection to the deleted Goal is removed.</p><p>If the objects were also linked to other parents or appeared in Roadmaps or Releases, those connections are unaffected.</p><hr><h2 id="i-don-t-see-goals-objectives-in-my-navigation" tabindex="-1">I don&#39;t see Goals &amp; Objectives in my navigation <a class="header-anchor" href="#i-don-t-see-goals-objectives-in-my-navigation" aria-label="Permalink to &quot;I don&#39;t see Goals &amp; Objectives in my navigation&quot;">​</a></h2><p>Goals &amp; Objectives is available to all workspace members. If it doesn&#39;t appear in your left-hand navigation, check with an Admin — navigation visibility can be affected by workspace configuration.</p><hr><h2 id="can-i-have-an-object-linked-to-more-than-one-goal" tabindex="-1">Can I have an object linked to more than one Goal? <a class="header-anchor" href="#can-i-have-an-object-linked-to-more-than-one-goal" aria-label="Permalink to &quot;Can I have an object linked to more than one Goal?&quot;">​</a></h2><p>Yes. An object can have multiple parents, including multiple Goals. This is useful for cross-cutting work that contributes to more than one objective. Link additional Goals from the Parents field on the object detail page.</p><hr><h2 id="the-downstream-view-shows-a-roadmap-i-wasn-t-expecting" tabindex="-1">The downstream view shows a Roadmap I wasn&#39;t expecting <a class="header-anchor" href="#the-downstream-view-shows-a-roadmap-i-wasn-t-expecting" aria-label="Permalink to &quot;The downstream view shows a Roadmap I wasn&#39;t expecting&quot;">​</a></h2><p>The downstream view includes any Roadmap that contains an object linked to this Goal — even if the connection was made indirectly. If an object was recently linked to this Goal and it&#39;s already on a Roadmap, the Roadmap will appear in the downstream view.</p><p>If you see a connection you don&#39;t expect, check the Parents field on the relevant object in the Backlog to see how it got linked.</p><hr><h2 id="can-i-reorder-goals" tabindex="-1">Can I reorder Goals? <a class="header-anchor" href="#can-i-reorder-goals" aria-label="Permalink to &quot;Can I reorder Goals?&quot;">​</a></h2><p>Goals are displayed in reverse creation order (most recently created first). There is no drag-to-reorder or manual sorting in the Goals &amp; Objectives module.</p>',26)])])}const b=a(i,[["render",s]]);export{m as __pageData,b as default};
